// Guide content (Turkish + English). Every guide is written "as if explaining to someone who has never done this":
// what it is, what you need, numbered steps (with a picture where a click is involved), things to ask Claude, limits,
// what to do when it does not work, and the safety note. The common first/last steps (switch on in ArchMCP, apply, see the
// tools in Claude) are added automatically by guides.js, so the lists below only hold what is specific to each program.
//
// step shape: { t: title, d: detail, img: { k: "menu"|"button"|"field"|"terminal"|"ports"|"ok"|..., ...params } }

const st = (t, d, img) => ({ t, d, ...(img ? { img } : {}) });
const menu = (app, ...path) => ({ k: "menu", app, path });
const btn = (label, caption) => ({ k: "button", label, caption });
const cmd = (cmd, where) => ({ k: "terminal", cmd, where });

